 "content": "def transform(grid):
    """Draw the directional number-strokes and mark their crossings."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    originals = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] in (1, 2, 3, 6)]
    horizontal_2 = []
    verticals = []

    # Render strokes based only on original markers.
    for r, c, color in originals:
        if color == 1:
            # Two-cell eastward trail; the 1 terminates one row above its far end.
            for x in (c + 1, c + 2):
                if 0 <= x < w and grid[r][x] == 0:
                    out[r][x] = 5
            if r - 1 >= 0 and c + 2 < w and grid[r - 1][c + 2] == 0:
                out[r - 1][c + 2] = 1
        elif color == 2:
            # Four-cell westward motif: endpoint 2, then three 5 cells, then source 2.
            left = c - 4
            for x in range(max(0, left), c):
                if grid[r][x] == 0:
                    out[r][x] = 5
            if left >= 0 and grid[r][left] == 0:
                out[r][left] = 2
            horizontal_2.append((r, left, c))
        elif color == 3:
            # Three cells south: two 5s followed by a terminal 3.
            for d in (1, 2):
                if r + d < h and grid[r + d][c] == 0:
                    out[r + d][c] = 5
            if r + 3 < h and grid[r + 3][c] == 0:
                out[r + 3][c] = 3
            verticals.append((c, r, min(h - 1, r + 3)))
        elif color == 6:
            # Six cells north: five 5s followed by a terminal 6.
            for d in range(1, 6):
                if r - d >= 0 and grid[r - d][c] == 0:
                    out[r - d][c] = 5
            if r - 6 >= 0 and grid[r - 6][c] == 0:
                out[r - 6][c] = 6
            verticals.append((c, max(0, r - 6), r))

    # A 2's horizontal motif crossing a 3/6 vertical stroke becomes a 4;
    # the crossing emits a southwest diagonal of 4s to the edge.
    crossings = []
    for vr, left, right in horizontal_2:
        for vc, top, bottom in verticals:
            if left <= vc <= right and top <= vr <= bottom:
                crossings.append((vr, vc))
    for r, c in crossings:
        out[r][c] = 4
    for r, c in crossings:
        rr, cc = r + 1, c - 1
        while rr < h and cc >= 0:
            if grid[rr][cc] == 0:
                out[rr][cc] = 4
            rr += 1
            cc -= 1
    return out


